head.b:skin:
:root{--yellow:#ffd200;--blue:#0066e6;--ink:#0f172a;--pale:#e8f2ff;--white:#fff;--line:#e0e8f2;--radius:24px;--header:94px;--shadow:0 12px 36px #0f172a0d}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:calc(var(--header) + 20px)}body{margin:0;background:var(--white);color:var(--ink);font-family:Inter,Arial,sans-serif;line-height:1.5}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit}a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}button,a{touch-action:manipulation}a:focus-visible,button:focus-visible{outline:3px solid var(--blue);outline-offset:5px}h1,h2,h3,.button,.slogan,.price,.wordmark{font-family:Montserrat,Arial,sans-serif}h1,h2,h3,p{margin:0}.container{width:min(1240px,calc(100% - 64px));margin-inline:auto}.skip{position:fixed;top:8px;left:8px;z-index:100;transform:translateY(-180%);padding:12px 20px;background:var(--white);border:2px solid var(--blue)}.skip:focus{transform:none}.site-header{position:sticky;top:0;z-index:20;background:#fffffff5;border-bottom:1px solid #edf1f7;backdrop-filter:blur(12px)}.header-inner{min-height:var(--header);display:flex;align-items:center;gap:24px}.brand{display:flex;align-items:center;gap:18px;flex-shrink:0}.brand img{width:106px;height:67px;object-fit:contain}.brand-caption{max-width:160px;font-size:14px;font-weight:500;line-height:1.4;border-left:1px solid #dbe3ec;padding-left:18px}.nav{margin-left:auto;display:flex;align-items:center;gap:25px}.nav a{font-size:14px;font-weight:600;white-space:nowrap;padding-block:12px}.nav a:hover{color:var(--blue)}.languages{display:flex;align-items:center;gap:3px;border:1px solid var(--line);border-radius:30px;padding:4px;flex-shrink:0}.languages button{border:0;background:transparent;padding:8px 10px;min-height:38px;border-radius:24px;font-size:13px;font-weight:700;cursor:pointer;color:var(--ink)}.languages button[aria-pressed=true]{color:var(--white);background:var(--blue)}.menu-toggle{display:none;background:white;border:1px solid var(--line);width:44px;height:44px;border-radius:12px;align-items:center;justify-content:center;color:var(--ink)}.icon{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.hero{position:relative;isolation:isolate;overflow:hidden;padding-top:42px;padding-bottom:100px}.hero-grid{display:grid;grid-template-columns:1fr 1.1fr;align-items:center;gap:8px;position:relative;z-index:2}.hero-copy{padding-block:12px 24px}.wordmark{font-size:clamp(74px,8.5vw,116px);font-style:italic;letter-spacing:-.075em;font-weight:900;line-height:1;margin-left:-5px;margin-bottom:14px}.hero h1{font-size:clamp(28px,3vw,42px);font-weight:800;letter-spacing:-.035em;line-height:1.2;max-width:530px}.slogan{display:inline-block;background:var(--yellow);border-radius:40px;padding:12px 25px;margin-top:23px;font-size:clamp(18px,2vw,25px);font-style:italic;font-weight:800;letter-spacing:-.025em;box-shadow:inset 0 3px 7px #fff8}.hero-benefits{display:flex;gap:22px;margin:29px 0 28px;padding:0;list-style:none}.hero-benefits li{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600;max-width:145px;line-height:1.4}.hero-benefits .icon{color:var(--blue);width:30px;height:30px}.button{display:inline-flex;align-items:center;justify-content:center;gap:13px;min-height:62px;padding:14px 36px;border-radius:36px;background:var(--yellow);font-size:23px;font-weight:800;box-shadow:0 8px 20px #ffd20030;transition:transform .2s,box-shadow .2s}.button:hover{transform:translateY(-3px);box-shadow:0 12px 25px #ffd20050}.button .icon{width:30px;height:30px}.hero-visual{position:relative;margin:0;padding-top:30px;align-self:center}.hero-visual:before{content:'';position:absolute;z-index:-1;inset:5% -15% -4% -5%;background:radial-gradient(ellipse,#e8f2ffb0,transparent 66%);border-radius:50%}.hero-image{width:100%;filter:drop-shadow(0 16px 16px #0f172a09)}.visual-note{font-size:12px;color:#526174;text-align:center;margin:12px auto 0;max-width:440px;line-height:1.5}.drop{position:absolute;z-index:-1;width:28px;height:35px;border:1px solid #64bded90;border-radius:62% 38% 55% 45%;background:radial-gradient(ellipse at 30% 23%,#fff 8%,#d8f1ff85 40%,#66c4f055 70%,#fff 95%);box-shadow:inset -2px -3px 5px #6db6e840,0 6px 8px #0084db12;transform:rotate(30deg);animation:float 6s ease-in-out infinite}.drop-one{top:1%;left:8%;width:35px;height:44px}.drop-two{top:10%;right:1%;animation-delay:-2s}.drop-three{bottom:13%;right:0;width:16px;height:21px;animation-delay:-4s}.prices{position:relative;z-index:3;display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:750px;margin:32px auto 0}.price-card{display:grid;grid-template-columns:112px 1fr;gap:16px;align-items:center;padding:15px 22px;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);background:var(--white);transition:transform .2s,border-color .2s}.price-card:hover{transform:translateY(-3px);border-color:var(--blue)}.price-card img{width:112px;height:100px;object-fit:contain}.price-card h2{font-size:18px;font-weight:800;line-height:1.25;margin-bottom:7px}.price{display:inline-block;font-size:24px;font-weight:800;line-height:1.1;padding:8px 18px;background:var(--yellow);border-radius:30px;white-space:nowrap}.price small{font-size:16px}.price-card.featured{border:2px solid var(--blue);position:relative}.featured .price{background:var(--blue);color:var(--white)}.saving{position:absolute;top:-14px;right:18px;background:var(--yellow);border-radius:20px;padding:4px 12px;font-size:12px;font-weight:700}.hero-waves{position:absolute;bottom:0;left:0;width:100%;height:115px;z-index:-1}.scroll-next{position:absolute;bottom:18px;left:calc(50% - 22px);display:flex;width:44px;height:44px;border-radius:50%;align-items:center;justify-content:center;background:white;border:1px solid #dce7f4;box-shadow:0 4px 12px #0f172a0d;z-index:5;color:var(--blue)}.placeholder{padding-block:55px;border-bottom:1px solid #edf1f7;scroll-margin-top:20px}.placeholder:nth-child(2n){background:#f8fbff}.placeholder h2{font-size:clamp(24px,3vw,32px);font-weight:800;letter-spacing:-.03em}.placeholder-space{height:38px;margin-top:22px;border-top:1px dashed #d7e3f2}.site-footer{padding-block:26px;color:#526174;font-size:14px}.site-footer .container{display:flex;justify-content:space-between;gap:20px}.blogger-system{display:none!important}.reveal{animation:appear .65s both}.hero-visual.reveal{animation-delay:.12s}@keyframes appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes float{50%{translate:0 -9px}}.js-reveal{transition:opacity .5s,transform .5s}.js-reveal.waiting{opacity:0;transform:translateY(14px)}
@media(min-width:1500px){.hero{padding-top:58px;padding-bottom:115px}.prices{margin-top:44px}}
@media(max-width:1100px){.container{width:calc(100% - 40px)}.brand-caption{display:none}.nav{gap:19px}.hero-benefits{gap:15px}.hero-benefits li{font-size:12px}.slogan{padding-inline:20px}.price-card{padding-inline:18px}}
@media(max-width:800px){:root{--header:78px}.header-inner{gap:12px}.brand img{width:90px;height:57px}.languages{margin-left:auto}.menu-toggle{display:flex}.nav{position:absolute;top:100%;left:0;right:0;background:white;box-shadow:0 16px 24px #0f172a14;border-bottom:1px solid var(--line);padding:16px 24px;display:none;flex-direction:column;align-items:stretch;gap:0}.nav.open{display:flex}.nav a{padding:13px 8px;font-size:16px}.hero{padding-top:30px}.hero-grid{grid-template-columns:1fr 1fr;gap:0}.wordmark{font-size:80px}.hero h1{font-size:29px}.slogan{font-size:18px;padding:11px 17px}.hero-benefits{flex-direction:column;gap:13px;margin-block:22px}.hero-benefits li{font-size:14px;max-width:none}.hero-benefits .icon{width:25px;height:25px}.button{font-size:20px;min-height:56px;padding:12px 28px}.hero-visual{padding-top:0}.visual-note{font-size:11px}.prices{margin-top:26px}.price-card{grid-template-columns:83px 1fr;padding:16px 13px;gap:10px}.price-card img{width:83px;height:85px}.price-card h2{font-size:16px}.price{font-size:23px;padding:8px 15px}}
@media(max-width:600px){.container{width:calc(100% - 32px)}.hero{padding-top:26px;padding-bottom:90px}.hero-grid{grid-template-columns:1fr}.hero-copy{text-align:center;padding:0}.wordmark{font-size:82px;margin:0 0 11px}.hero h1{font-size:32px;max-width:350px;margin:auto}.slogan{margin-top:18px;font-size:19px;padding:12px 21px}.hero-benefits{flex-direction:row;justify-content:center;gap:12px;margin:23px 0}.hero-benefits li{flex:1;flex-direction:column;gap:7px;font-size:12px;max-width:110px}.hero-benefits .icon{width:28px;height:28px}.button{min-width:220px}.hero-visual{margin:20px -6px 0}.hero-image{width:100%;max-width:490px;margin:auto}.visual-note{margin-top:4px;font-size:11px;max-width:305px}.drop-one{left:5%;top:0;width:24px;height:31px}.drop-two{right:6%;width:18px;height:24px}.prices{gap:12px;margin-top:28px}.price-card{grid-template-columns:1fr;justify-items:center;text-align:center;gap:6px;padding:13px 8px 16px;border-radius:20px}.price-card img{width:105px;height:82px}.price-card h2{font-size:15px;margin-bottom:8px}.price{font-size:23px;padding:8px 15px}.price small{font-size:14px}.saving{font-size:10px;right:50%;transform:translateX(50%);white-space:nowrap;padding:4px 9px}.hero-waves{height:76px}.scroll-next{bottom:10px}.placeholder{padding-block:38px}.site-footer .container{flex-direction:column;gap:6px}}
@media(max-width:350px){.hero h1{font-size:28px}.slogan{font-size:17px;padding-inline:15px}.hero-benefits{gap:7px}.price{font-size:21px;padding-inline:12px}.languages button{padding:8px}.header-inner{gap:8px}}
/* KLIK v1.1 — approved comparison; hero rules above stay unchanged. */
.problem{position:relative;overflow:hidden;padding:72px 0 92px;background:linear-gradient(#f8fbff,#fff 38%,#fff 85%,#f7fbff)}.problem-heading{text-align:center;margin-bottom:34px}.problem-heading h2{font-size:clamp(30px,3.2vw,44px);font-weight:800;letter-spacing:-.04em;line-height:1.2}.problem-subtitle{font-family:Montserrat,Arial,sans-serif;font-size:clamp(18px,2vw,23px);font-weight:700;color:var(--blue);margin-top:12px}.comparison-grid{display:grid;grid-template-columns:minmax(0,1fr) 56px minmax(0,1fr);align-items:center;gap:0}.comparison-card{overflow:hidden;border:3px solid var(--blue);border-radius:30px;background:white;box-shadow:0 14px 36px #0066e60d}.comparison-copy{text-align:center;padding:22px 20px 20px;background:linear-gradient(135deg,#e8f2ff,#fff)}.comparison-copy h3{font-size:clamp(25px,3vw,34px);line-height:1.2;font-weight:800;font-style:italic;margin:0 0 15px}.comparison-copy h3 span{display:inline-block;background:#e8f2ff;border-radius:40px;padding:10px 30px}.comparison-after h3 span{background:var(--yellow)}.comparison-copy p{max-width:360px;margin:auto;font-size:clamp(16px,1.5vw,19px);line-height:1.45;font-weight:600;min-height:2.9em}.comparison-card>img{width:100%;aspect-ratio:714/640;object-fit:cover}.comparison-arrow{position:relative;z-index:2;width:110px;margin-left:-27px;filter:drop-shadow(0 5px 5px #0f172a22)}.comparison-arrow svg{display:block;width:100%;height:auto}.comparison-note{text-align:center;max-width:820px;margin:26px auto 0;font-size:13px;line-height:1.6;color:#526174}.problem-wave{position:absolute;left:0;bottom:0;width:100%;height:48px}.compare-piece{transition:opacity .65s ease,translate .65s ease}.comparison-motion:not(.is-visible) .compare-piece{opacity:0;translate:0 16px}.comparison-motion.is-visible .comparison-before{transition-delay:.15s}.comparison-motion.is-visible .comparison-arrow{transition-delay:.35s}.comparison-motion.is-visible .comparison-after{transition-delay:.55s}@media(max-width:650px){.problem{padding:42px 0 65px}.problem-heading{margin-bottom:25px}.comparison-grid{grid-template-columns:minmax(0,1fr);gap:0;max-width:480px;margin:auto}.comparison-copy{padding:18px 16px 14px}.comparison-copy h3{font-size:29px;margin-bottom:12px}.comparison-copy p{font-size:17px;min-height:0;max-width:300px}.comparison-arrow{width:78px;margin:3px auto;transform:rotate(90deg)}.comparison-card{border-radius:25px}.comparison-note{font-size:12px;margin-top:22px}.problem-wave{height:34px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}.js-reveal.waiting,.comparison-motion:not(.is-visible) .compare-piece{opacity:1;transform:none;translate:none}}

body.script:
/* KLIK v1.1 — centralized translations; no order submission. */
(() => {
 'use strict';
 const translations = {
  uk:{product:'Магнітна кнопка для води',benefits:'Переваги',how:'Як користуватись',priceNav:'Ціна',faqNav:'FAQ',contacts:'Контакти',slogan:'Один клік – вільні руки!',easy:'Зручно та просто',time:'Економія часу',magnet:'Надійний магніт',order:'Замовити',one:'Одна кнопка',two:'Дві кнопки',saving:'Економія 99 грн',currency:'грн',note:'Синій колір — візуалізація. Відтінок готового виробу може відрізнятися.',problem:'Знайома ситуація?',solution:'KLIK – просте рішення',howTitle:'Як користуватися',benefitsTitle:'Переваги KLIK',construction:'Як влаштована кнопка',colors:'Обери свій колір',orderTitle:'Вартість та замовлення',delivery:'Доставка та оплата',faqTitle:'Часті запитання',skip:'До основного вмісту',menu:'Відкрити меню',closeMenu:'Закрити меню',nav:'Основна навігація',language:'Мова сайту',next:'До наступного розділу',home:'KLIK — на початок',heroAlt:'Жовта магнітна кнопка KLIK та цифрова візуалізація синьої кнопки з декоративними бризками води',singleAlt:'Одна жовта магнітна кнопка KLIK',pairAlt:'Жовта кнопка KLIK та візуалізація синьої',footer:'Магнітна кнопка для води',prices:'Варіанти комплекту'},
  ru:{product:'Магнитная кнопка для воды',benefits:'Преимущества',how:'Как пользоваться',priceNav:'Цена',faqNav:'FAQ',contacts:'Контакты',slogan:'Один клик – свободные руки!',easy:'Удобно и просто',time:'Экономия времени',magnet:'Надёжный магнит',order:'Заказать',one:'Одна кнопка',two:'Две кнопки',saving:'Экономия 99 грн',currency:'грн',note:'Синий цвет — визуализация. Оттенок готового изделия может отличаться.',problem:'Знакомая ситуация?',solution:'KLIK – простое решение',howTitle:'Как пользоваться',benefitsTitle:'Преимущества KLIK',construction:'Как устроена кнопка',colors:'Выбери свой цвет',orderTitle:'Стоимость и заказ',delivery:'Доставка и оплата',faqTitle:'Частые вопросы',skip:'К основному содержимому',menu:'Открыть меню',closeMenu:'Закрыть меню',nav:'Основная навигация',language:'Язык сайта',next:'К следующему разделу',home:'KLIK — в начало',heroAlt:'Жёлтая магнитная кнопка KLIK и цифровая визуализация синей кнопки с декоративными брызгами воды',singleAlt:'Одна жёлтая магнитная кнопка KLIK',pairAlt:'Жёлтая кнопка KLIK и визуализация синей',footer:'Магнитная кнопка для воды',prices:'Варианты комплекта'}
 };
 Object.assign(translations.uk,{difference:'Відчуй різницю з KLIK!',before:'До KLIK',after:'З KLIK',beforeDescription:'Доводиться постійно утримувати кнопку',afterDescription:'Вода набирається, а твої руки вільні',beforeAlt:'Демонстраційна візуалізація: людина утримує пальцем кнопку подачі води',afterAlt:'Демонстраційна візуалізація: жовта кнопка KLIK на автоматі, вода надходить у пляшку без руки',comparisonNote:'Демонстраційна цифрова візуалізація, а не фотографія випробувань. Сумісність із конкретним автоматом потребує перевірки.'});
 Object.assign(translations.ru,{difference:'Почувствуй разницу с KLIK!',before:'До KLIK',after:'С KLIK',beforeDescription:'Приходится постоянно удерживать кнопку',afterDescription:'Вода набирается, а твои руки свободны',beforeAlt:'Демонстрационная визуализация: человек удерживает пальцем кнопку подачи воды',afterAlt:'Демонстрационная визуализация: жёлтая кнопка KLIK на автомате, вода поступает в бутылку без руки',comparisonNote:'Демонстрационная цифровая визуализация, а не фотография испытаний. Совместимость с конкретным автоматом требует проверки.'});
 let language='uk';
 const toggle=document.querySelector('.menu-toggle');
 const nav=document.querySelector('.nav');
 function setMenu(open){nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',translations[language][open?'closeMenu':'menu']);}
 function applyLanguage(value){
  language=Object.hasOwn(translations,value)?value:'uk';
  const dict=translations[language]; document.documentElement.lang=language;
  document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=dict[el.dataset.i18n];});
  document.querySelectorAll('[data-i18n-alt]').forEach(el=>el.alt=dict[el.dataset.i18nAlt]);
  document.querySelectorAll('[data-i18n-label]').forEach(el=>el.setAttribute('aria-label',dict[el.dataset.i18nLabel]));
  document.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));
  setMenu(false);
 }
 try{language=localStorage.getItem('klik.language')||'uk';}catch(_){}
 applyLanguage(language);
 document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{applyLanguage(button.dataset.language);try{localStorage.setItem('klik.language',language);}catch(_){} }));
 toggle.addEventListener('click',()=>setMenu(toggle.getAttribute('aria-expanded')!=='true'));
 nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setMenu(false)));
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){setMenu(false);toggle.focus();}});
 document.addEventListener('click',event=>{if(!event.target.closest('.site-header'))setMenu(false);});
 const mobile=matchMedia('(max-width:800px)'); mobile.addEventListener('change',()=>setMenu(false));
 if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('waiting');observer.unobserve(entry.target);}}),{threshold:.1});
  document.querySelectorAll('.placeholder').forEach(el=>{el.classList.add('js-reveal','waiting');observer.observe(el);});
  const problem=document.querySelector('.problem');
  if(problem){const sequence=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){problem.classList.add('is-visible');sequence.disconnect();}},{threshold:.08});problem.classList.add('comparison-motion');sequence.observe(problem);}
 }
})();
